36: 		frame:SetPoint("TOPLEFT", scrollTarget, "TOPLEFT", offset, -indent);
37: 		if not elementStretchDisabled then
38: 			frame:SetPoint("BOTTOMLEFT", scrollTarget, "BOTTOMLEFT", offset, 0);
39: 		end
40: 		return frame:GetWidth();
41: 	else
42: 		frame:SetPoint("TOPLEFT", scrollTarget, "TOPLEFT", indent, -offset);
43: 		if not elementStretchDisabled then
44: 			frame:SetPoint("TOPRIGHT", scrollTarget, "TOPRIGHT", 0, -offset);
45: 		end
46: 		return frame:GetHeight();
